<script setup>
import{onMounted,reactive,ref}from'vue';import{publicEvaluationApi as api}from'../../publicEvaluationApi'
const rows=ref([]),orgs=ref([]),requests=ref([]),audits=ref([]),detail=ref(null),sensitive=ref(null),message=ref('');const f=reactive({orgUnitId:'',source:'',status:'',minScore:'',anonymous:''})
async function load(){try{[rows.value,orgs.value,requests.value,audits.value]=await Promise.all([api.list(f),api.orgs(),api.requests(),api.audits()])}catch(e){message.value=e.message}}
async function open(x){detail.value=await api.detail(x.id)}
async function process(x){const status=prompt('处理状态：PENDING / PROCESSING / RESOLVED / IGNORED',x.process_status);if(!status)return;const opinion=prompt('处理意见','')||'';try{await api.process(x.id,{status,opinion});await load()}catch(e){message.value=e.message}}
async function request(x){const reason=prompt('模拟敏感原文访问原因');if(!reason)return;try{await api.requestAccess(x.id,{reason,requestedFields:'姓名,手机号,身份证号'});message.value='模拟访问申请已提交';await load()}catch(e){message.value=e.message}}
async function review(x,action){const opinion=prompt(action==='APPROVE'?'批准意见':'驳回意见');if(!opinion)return;await api.reviewRequest(x.id,{action,opinion});await load()}
async function reveal(x){try{sensitive.value=await api.reveal(x.id);await load()}catch(e){message.value=e.message}}
onMounted(load)
</script>
<template><section class="page active"><div class="alert alert-warning">默认仅显示脱敏信息。敏感原文访问是明确标记的本地模拟审批，不代表真实权限控制。</div><div v-if="message" class="alert alert-info">{{message}}</div>
<div class="card"><div class="card-header"><h3>🔐 评价数据与隐私脱敏</h3><button class="btn btn-outline" @click="load">刷新</button></div><div class="search-bar"><select v-model="f.orgUnitId"><option value="">全部机构</option><option v-for="o in orgs" :key="o.id" :value="o.id">{{o.unit_name}}</option></select><select v-model="f.source"><option value="">全部来源</option><option value="LOCAL">本地评价</option><option value="HOTLINE_12345">12345</option><option value="GOV_SERVICE">好差评</option><option value="GOV_PLATFORM">政务平台</option></select><select v-model="f.status"><option value="">全部状态</option><option value="PENDING">待处理</option><option value="PROCESSING">处理中</option><option value="RESOLVED">已解决</option><option value="IGNORED">已忽略</option></select><select v-model="f.anonymous"><option value="">实名/匿名</option><option value="true">匿名</option><option value="false">实名</option></select><button class="btn btn-primary" @click="load">查询</button></div>
<table><thead><tr><th>编号</th><th>机构</th><th>来源</th><th>评分</th><th>评价人</th><th>手机号</th><th>情感</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="!rows.length"><td colspan="9">暂无数据</td></tr><tr v-for="x in rows" :key="x.id"><td>{{x.evaluation_no}}</td><td>{{x.unit_name}}</td><td>{{x.source}}</td><td>{{x.overall_score}}</td><td>{{x.masked_name}}</td><td>{{x.masked_phone}}</td><td>{{x.sentiment}}</td><td>{{x.process_status}}</td><td><button class="btn btn-sm btn-outline" @click="open(x)">详情</button> <button class="btn btn-sm btn-outline" @click="process(x)">处理</button> <button class="btn btn-sm btn-primary" @click="request(x)">申请原文</button></td></tr></tbody></table></div>
<div class="card"><div class="card-header"><h3>👁️ 模拟敏感访问申请与审计</h3></div><table><thead><tr><th>评价编号</th><th>原因</th><th>字段</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="!requests.length"><td colspan="5">暂无申请</td></tr><tr v-for="x in requests" :key="x.id"><td>{{x.evaluation_no}}</td><td>{{x.reason}}</td><td>{{x.requested_fields}}</td><td>{{x.status}}</td><td><template v-if="x.status==='PENDING'"><button class="btn btn-sm btn-primary" @click="review(x,'APPROVE')">批准</button> <button class="btn btn-sm btn-outline" @click="review(x,'REJECT')">驳回</button></template><button v-if="x.status==='APPROVED'" class="btn btn-sm btn-outline" @click="reveal(x)">查看原文</button></td></tr></tbody></table><div class="alert alert-info">原文访问审计 {{audits.length}} 次</div></div>
<div v-if="detail" class="modal-overlay" @click.self="detail=null"><div class="modal"><h3>评价详情（脱敏）</h3><p>{{detail.unit_name}} / {{detail.item_name||detail.source_service_item}}</p><p>四项评分：{{detail.convenience_score||'-'}} / {{detail.attitude_score||'-'}} / {{detail.timeliness_score||'-'}} / {{detail.clarity_score||'-'}}</p><p>评价内容：{{detail.comment_text||'-'}}</p><button class="btn btn-outline" @click="detail=null">关闭</button></div></div>
<div v-if="sensitive" class="modal-overlay" @click.self="sensitive=null"><div class="modal"><h3>敏感原文（模拟授权）</h3><p>姓名：{{sensitive.evaluator_name||'-'}}</p><p>手机号：{{sensitive.evaluator_phone||'-'}}</p><p>身份证号：{{sensitive.evaluator_id_no||'-'}}</p><button class="btn btn-outline" @click="sensitive=null">关闭</button></div></div>
</section></template>
<style scoped>.modal-overlay{position:fixed;inset:0;background:#0006;z-index:1000;display:flex;align-items:center;justify-content:center}.modal{background:#fff;padding:22px;border-radius:12px;width:min(650px,92vw)}</style>
